import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`social-calendar`,heroTitle:`Fill your social calendar in minutes`,heroSubtitle:`Perplexity Computer analyzes your brand, writes 30 days of posts, and builds your content calendar — automatically.`,inputUrlCta:`Build my calendar`,inputUrlPlaceholder:`yourbrand.com`,inputUrlPrefill:`Go to {url} and analyze the brand voice, audience, and visual style. Then generate a 30-day social media content calendar across LinkedIn, Instagram, and X. For each post, include: 1) Platform-specific caption tailored to the tone and format of that platform, 2) Relevant hashtags, 3) Optimal posting day and time based on platform best practices. Organize everything into a structured calendar view with columns for date, platform, caption, hashtags, and posting time.`,heroOverlaySteps:[`Analyzing your brand voice, audience, and visual identity`,`Writing 30 days of posts tailored for LinkedIn, Instagram, and X`,`Generating hashtags and optimal posting times for each platform`,`Content calendar with captions, hashtags, and scheduling — ready to publish`],generatingSteps:[`Visiting {url} to extract your brand voice, audience, and positioning`,`Designing an agent to write platform-specific posts for LinkedIn, Instagram, and X`,`Configuring hashtag research and optimal posting schedules for each platform`,`Setting up your 30-day content calendar with captions, hashtags, and time slots`],featureSectionTitle:`From brand to full calendar`,featureCardTitles:[`Connects to your marketing stack`,`Outputs you can publish`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Notion, Canva, Google Analytics, Slack — Computer plugs into your tools so posts go from draft to scheduled in one workflow.`,`Platform-specific captions. Curated hashtag sets. Optimal posting times. A structured 30-day calendar you can hand to your team or load into your scheduler.`],capabilitySectionTitle:`Your content team, on autopilot`,capabilitySectionSubtitle:`Describe your brand, step away, come back to a month of ready-to-post content.`,capabilityCards:[{title:`Brand Analysis`,description:`Computer can study your website, competitors, and audience — then extract the voice, tone, and themes that define your brand online.`},{title:`Post Drafting`,description:`Computer can write captions tailored to each platform's format — punchy threads for X, professional insights for LinkedIn, visual hooks for Instagram.`},{title:`Hashtag Research`,description:`Computer can research trending and niche hashtags for every post — matched to your industry, audience, and platform for maximum reach.`},{title:`Connect Your Tools`,description:`Computer can read and write to Google Sheets, Notion, Canva, Slack, and more — build workflows across your entire content stack.`},{title:`Remember & Learn`,description:`Computer can remember your brand voice, top-performing formats, and audience preferences across sessions — so every calendar gets sharper.`},{title:`Monitor & Alert`,description:`Computer can track engagement patterns and flag when content themes over- or underperform — so you can adjust your calendar in real time.`}]});export{t as default};
